<content>import { createClient } from '@supabase/supabase-js'

const supabaseUrl = import.meta.env.VITE_SUPABASE_URL || 'https://demo.supabasedb.co'
const supabaseAnonKey = import.meta.env.VITE_SUPABASE_ANON_KEY || 'demo-key'

export const supabase = createClient(supabaseUrl, supabaseAnonKey)

// Database Types
export interface Student {
  id: string
  name: string
  grade: string
  phone: string
  address: string
  bus_id?: string
  parent_name: string
  parent_phone: string
  created_at: string
}

export interface Bus {
  id: string
  number: string
  driver_name: string
  driver_phone: string
  capacity: number
  route: string
  status: 'active' | 'maintenance' | 'inactive'
  created_at: string
}

export interface Route {
  id: string
  name: string
  stops: string[]
  estimated_time: number
  distance: number
  bus_id?: string
  created_at: string
}

export interface Trip {
  id: string
  bus_id: string
  route_id: string
  departure_time: string
  arrival_time?: string
  status: 'scheduled' | 'in_progress' | 'completed' | 'cancelled'
  students_count: number
  created_at: string
}
</content>
