      if (error) throw error
      if (data) {
        setBuses(prev => prev.map(b => b.id === id ? data[0] : b))
      }
      return { success: true }
    } catch (err) {
      return { success: false, error: err instanceof Error ? err.message : 'خطأ في تحديث بيانات الحافلة' }
    }
  }

  useEffect(() => {
    fetchBuses()
  }, [])

  return {
    buses,
    loading,
    error,
    addBus,
    updateBus,
    refetch: fetchBuses
  }
}

// Routes Hook
export const useRoutes = () => {
  const [routes, setRoutes] = useState<Route[]>([])
  const [loading, setLoading] = useState(true)

  const fetchRoutes = async () => {
    try {
      setLoading(true)
      const { data, error } = await supabase
        .from('routes')
        .select('*')
        .order('name', { ascending: true })

      if (error) throw error
      setRoutes(data || [])
    } catch (err) {
      console.error('Error fetching routes:', err)
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    fetchRoutes()
  }, [])

  return { routes, loading, refetch: fetchRoutes }
}
