<content>import { useState, useEffect } from 'react'
import { supabase, Student, Bus, Route, Trip } from '../lib/supabase'

// Students Hook
export const useStudents = () => {
  const [students, setStudents] = useState<Student[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  const fetchStudents = async () => {
    try {
      setLoading(true)
      const { data, error } = await supabase
        .from('students')
        .select('*')
        .order('created_at', { ascending: false })

      if (error) throw error
      setStudents(data || [])
    } catch (err) {
      setError(err instanceof Error ? err.message : 'خطأ في جلب بيانات الطلاب')
    } finally {
      setLoading(false)
    }
  }

  const addStudent = async (student: Omit<Student, 'id' | 'created_at'>) => {
    try {
      const { data, error } = await supabase
        .from('students')
        .insert([student])
        .select()

      if (error) throw error
      if (data) {
        setStudents(prev => [data[0], ...prev])
      }
      return { success: true }
    } catch (err) {
      return { success: false, error: err instanceof Error ? err.message : 'خطأ في إضافة الطالب' }
    }
  }

  const updateStudent = async (id: string, updates: Partial<Student>) => {
    try {
      const { data, error } = await supabase
        .from('students')
        .update(updates)
        .eq('id', id)
        .select()

      if (error) throw error
      if (data) {
        setStudents(prev => prev.map(s => s.id === id ? data[0] : s))
      }
      return { success: true }
    } catch (err) {
      return { success: false, error: err instanceof Error ? err.message : 'خطأ في تحديث بيانات الطالب' }
    }
  }

  const deleteStudent = async (id: string) => {
    try {
      const { error } = await supabase
        .from('students')
        .delete()
        .eq('id', id)

      if (error) throw error
      setStudents(prev => prev.filter(s => s.id !== id))
      return { success: true }
    } catch (err) {
      return { success: false, error: err instanceof Error ? err.message : 'خطأ في حذف الطالب' }
    }
  }

  useEffect(() => {
    fetchStudents()
  }, [])

  return {
    students,
    loading,
    error,
    addStudent,
    updateStudent,
    deleteStudent,
    refetch: fetchStudents
  }
}

// Buses Hook
export const useBuses = () => {
  const [buses, setBuses] = useState<Bus[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  const fetchBuses = async () => {
    try {
      setLoading(true)
      const { data, error } = await supabase
        .from('buses')
        .select('*')
        .order('number', { ascending: true })

      if (error) throw error
      setBuses(data || [])
    } catch (err) {
      setError(err instanceof Error ? err.message : 'خطأ في جلب بيانات الحافلات')
    } finally {
      setLoading(false)
    }
  }

  const addBus = async (bus: Omit<Bus, 'id' | 'created_at'>) => {
    try {
      const { data, error } = await supabase
        .from('buses')
        .insert([bus])
        .select()

      if (error) throw error
      if (data) {
        setBuses(prev => [...prev, data[0]].sort((a, b) => a.number.localeCompare(b.number)))
      }
      return { success: true }
    } catch (err) {
      return { success: false, error: err instanceof Error ? err.message : 'خطأ في إضافة الحافلة' }
    }
  }

  const updateBus = async (id: string, updates: Partial<Bus>) => {
    try {
      const { data, error } = await supabase
        .from('buses')
        .update(updates)
        .eq('id', id)
        .select()

      if (error) throw error
      if (data) {
        setBuses(prev => prev.map(b => b.id === id ? data[0] : b))
      }
      return { success: true }
    } catch (err) {
      return { success: false, error: err instanceof Error ? err.message : 'خطأ في تحديث بيانات الحافلة' }
    }
  }

  useEffect(() => {
    fetchBuses()
  }, [])

  return {
    buses,
    loading,
    error,
    addBus,
    updateBus,
    refetch: fetchBuses
  }
}

// Routes Hook
export const useRoutes = () => {
  const [routes, setRoutes] = useState<Route[]>([])
  const [loading, setLoading] = useState(true)

  const fetchRoutes = async () => {
    try {
      setLoading(true)
      const { data, error } = await supabase
        .from('routes')
        .select('*')
        .order('name', { ascending: true })

      if (error) throw error
      setRoutes(data || [])
    } catch (err) {
      console.error('Error fetching routes:', err)
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    fetchRoutes()
  }, [])

  return { routes, loading, refetch: fetchRoutes }
}
